"""읽기·근거 선택·판단을 연결하는 게임 내부 조사 화면."""
import json
from investigation_content import CASES
IQ_CSS_PY = '<style>\n.iq-card{border:2.5px solid #F5C99B!important;border-radius:20px!important;padding:14px 16px!important;margin:12px 0!important;background:#fff;box-shadow:0 4px 0 #F5D9B5}\n.iq-done{border-color:#86EFAC!important;box-shadow:0 4px 0 #BBF7D0;background:#F0FDF4}\n.iq-done details summary{cursor:pointer;font-weight:800;color:#166534}\n.iq-got{display:inline-block;margin-left:6px;background:#16A34A;color:#fff;border-radius:999px;padding:2px 10px;font-size:.85rem;animation:iqpop .5s}\n@keyframes iqpop{0%{transform:scale(.3)}70%{transform:scale(1.15)}100%{transform:scale(1)}}\n.iq-head{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:6px}\n.iq-head h3{margin:0}\n.iq-steps{display:flex;gap:4px}\n.iq-step{background:#F1F5F9;color:#94A3B8;border-radius:999px;padding:3px 10px;font-weight:800;font-size:.85rem}\n.iq-step.now{background:#F97316;color:#fff;box-shadow:0 0 0 3px #FED7AA}\n.iq-step.ok{background:#DCFCE7;color:#166534}\n.iq-src,.iq-opts,.iq-proof{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}\n.iq-doc{background:#FFF7ED!important;border:2px solid #FDBA74!important;color:#7C2D12!important;border-radius:14px!important;font-weight:800}\n.iq-doc.seen{background:#fff!important;border-color:#CBD5E1!important;color:#334155!important}\n.iq-doc.open{border-color:#F97316!important;box-shadow:0 0 0 3px #FED7AA}\n.iq-q{font-weight:900;font-size:1.05rem;color:#1F2937;margin-top:8px}\n.iq-opts{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}\n.iq-opt,.iq-pf{text-align:left!important;background:#fff!important;border:2px solid #E2E8F0!important;color:#1F2937!important;border-radius:14px!important;padding:10px 12px!important;font-weight:700;line-height:1.45}\n.iq-opt:hover,.iq-pf:hover{border-color:#F97316!important}\n.iq-opt.on{border-color:#2563EB!important;background:#EFF6FF!important;box-shadow:0 0 0 3px #BFDBFE}\n.iq-pf.on{border-color:#16A34A!important;background:#F0FDF4!important}\n.iq-act{display:flex;gap:8px}\n.iq-go{flex:1;background:#F97316!important;color:#fff!important;border:0!important;font-size:1.1rem!important;font-weight:900;border-radius:14px!important;box-shadow:0 4px 0 #C2410C}\n.iq-go:disabled{background:#E2E8F0!important;color:#94A3B8!important;box-shadow:none}\n.iq-err{margin-top:8px;background:#FEF2F2;border-radius:12px;padding:8px 12px;font-weight:800;color:#9B1C1C}\n.iq-hints{margin-top:8px;background:#FFFBEB;border:2px solid #FCD34D;border-radius:12px;padding:8px 12px;line-height:1.6}\n</style>'
JS = '\nconst IQ_STATE={};\nfunction iqState(i){return IQ_STATE[i]||(IQ_STATE[i]={seen:[],selected:[],choice:\'\',view:null,done:false,error:\'\',hints:0,tries:0});}\nfunction iqMark(t){const C={\'가\':\'#DBEAFE;color:#1E40AF;border-color:#60A5FA\',\'나\':\'#FEF3C7;color:#92400E;border-color:#FBBF24\',\'다\':\'#DCFCE7;color:#166534;border-color:#4ADE80\',\'라\':\'#F3E8FF;color:#6B21A8;border-color:#C084FC\'};return esc(t).replace(/익명 판매자 ([가나다라])/g,(m,k)=>\'<b style="border:2px solid;background:\'+C[k]+\';padding:1px 8px;border-radius:999px;white-space:nowrap;font-weight:900">🕵️ 익명 판매자 \'+k+\'</b>\');}\nfunction iqSource(source){\n // 게임마다 자료를 보여 주는 모양이 달라요: 중고거래는 \'도토리마켓\' 앱 화면, 노노그램은 감식 자료 카드.\n const th=(typeof IQ_THEME!==\'undefined\')?IQ_THEME:\'\';\n if(th===\'market\') return `<article style="max-width:460px;margin:14px auto;background:#FDBA74;border-radius:26px;padding:6px;box-shadow:0 6px 16px #F9731633"><div style="background:#FFF7ED;border-radius:22px;overflow:hidden"><div style="background:#F97316;color:#fff;padding:10px 14px;font-weight:900">🛍️ 도토리마켓 · ${iqMark(source[1])}</div><div style="padding:12px 14px"><div style="background:#fff;border-radius:4px 16px 16px 16px;padding:10px 12px;box-shadow:0 1px 3px #0002;font-size:1.05rem;line-height:1.75">${iqMark(source[2])}</div></div></div></article>`;\n if(th===\'lab\') return `<article style="position:relative;margin:16px 0;background:#FFFDF5;border:1px solid #E5DCC3;border-radius:6px;padding:16px 16px 12px;box-shadow:0 6px 14px #0002;transform:rotate(-.6deg)"><span style="position:absolute;top:-10px;left:18px;background:#FDE68A;border:1px solid #E7C55A;padding:2px 10px;font-weight:900;font-size:.85rem;transform:rotate(-3deg)">🏷️ 감식 자료</span><b style="font-size:1.05rem">${iqMark(source[1])}</b><p style="font-size:1.05rem;line-height:1.75;margin:.5rem 0 0">${iqMark(source[2])}</p></article>`;\n return `<article style="background:#f0f5f2;padding:14px;margin:12px 0;border-left:5px solid #39756b"><b style="font-size:1.05rem">${iqMark(source[1])}</b><p style="font-size:1.05rem;line-height:1.75;margin:.5rem 0 0">${iqMark(source[2])}</p></article>`;\n}\nfunction iqHTML(i){\n const c=IQ_CASES[i],s=iqState(i);\n const source=c.sources.find(x=>x[0]===s.view);\n const n=c.proof.length;\n if(s.done) return `<section class="box iq-card iq-done"><h3>✅ ${esc(c.title)} <span class="iq-got">🔍 단서 획득!</span></h3><details><summary>📖 풀이 보기</summary>${iqSolution(c)}</details></section>`;\n const step=s.seen.length===0?1:(s.choice===\'\'?2:3);\n const tab=(k,t)=>`<span class="iq-step${step===k?\' now\':\'\'}${step>k?\' ok\':\'\'}">${step>k?\'✓\':k} ${t}</span>`;\n return `<section class="box iq-card">\n <div class="iq-head"><h3>${esc(c.title)}</h3><div class="iq-steps">${tab(1,\'📄 읽기\')}${tab(2,\'🎯 결론\')}${tab(3,\'✅ 근거 \'+n+\'개\')}</div></div>\n <div class="iq-src">${c.sources.map(x=>{const lock=x[3]&&!s.seen.includes(x[3]);const seen=s.seen.includes(x[0]);return `<button class="iq-doc${seen?\' seen\':\'\'}${s.view===x[0]?\' open\':\'\'}" onclick="iqOpen(${i},\'${x[0]}\')" ${lock?\'disabled title="앞 자료를 먼저 읽어요"\':\'\'}>${lock?\'🔒\':(seen?\'📖\':\'📄\')} ${iqMark(x[1])}</button>`;}).join(\'\')}</div>\n ${source?iqSource(source):\'\'}\n ${s.seen.length?`<div class="iq-q">🎯 ${esc(c.question)}</div>\n <div class="iq-opts">${c.options.map((v,k)=>`<button class="iq-opt${String(k)===s.choice?\' on\':\'\'}" onclick="iqState(${i}).choice=\'${k}\';iqState(${i}).error=\'\';render()">${esc(v)}</button>`).join(\'\')}</div>`:\'\'}\n ${s.choice!==\'\'?`<div class="iq-q">✅ 증거 자료 ${n}개 고르기 <small>(${s.selected.length}/${n})</small></div>\n <div class="iq-proof">${c.sources.filter(x=>s.seen.includes(x[0])).map(x=>{const on=s.selected.includes(x[0]);return `<button class="iq-pf${on?\' on\':\'\'}" onclick="iqSelect(${i},\'${x[0]}\',${!on})">${on?\'✅\':\'⬜\'} ${iqMark(x[1])}</button>`;}).join(\'\')}</div>\n <div class="iq-act"><button class="iq-go" onclick="iqCheck(${i})" ${s.selected.length===n?\'\':\'disabled\'}>🔍 제출</button><button class="iq-hint" onclick="iqHint(${i})" ${s.hints>=iqHintList(c).length?\'disabled\':\'\'}>💡 힌트 ${Math.min(s.hints,iqHintList(c).length)}/${iqHintList(c).length}</button></div>`:\'\'}\n ${s.error?`<div class="iq-err">${esc(s.error)}</div>`:\'\'}\n ${s.hints?\'<div class="iq-hints">\'+iqHintList(c).slice(0,s.hints).map((h,k)=>\'<div>💡 \'+esc(h)+\'</div>\').join(\'\')+\'</div>\':\'\'}\n </section>`;\n}\nfunction iqOpen(i,k){const c=IQ_CASES[i],s=iqState(i),x=c.sources.find(x=>x[0]===k);if(!x||(x[3]&&!s.seen.includes(x[3])))return;if(!s.seen.includes(k))s.seen.push(k);s.view=k;render();}\nfunction iqSelect(i,k,on){const s=iqState(i);s.error=\'\';s.selected=s.selected.filter(x=>x!==k);if(on&&s.seen.includes(k))s.selected.push(k);render();}\nfunction iqHintList(c){return c.hints&&c.hints.length?c.hints:[c.hint];}\n// 다 풀면 정답 결론과 자료마다 왜 근거인지/아닌지를 풀이로 보여 줘요.\nfunction iqSolution(c){\n // 풀이를 1단계(자료 읽기) → 2단계(결론) → 3단계(근거)로 나눠 보여 줘요.\n const rows=c.sources.map(x=>{const ok=c.proof.includes(x[0]);return \'<tr><td style="padding:6px 8px;white-space:nowrap;font-weight:800;color:\'+(ok?\'#166534\':\'#9A3412\')+\'">\'+(ok?\'✅ 근거\':\'❌ 아님\')+\'</td><td style="padding:6px 8px"><b>\'+iqMark(x[1])+\'</b><br>\'+esc((c.why||{})[x[0]]||\'\')+\'</td></tr>\';}).join(\'\');\n const step=(n,t,body)=>\'<div style="margin-top:10px"><div style="font-weight:900;color:#166534"><span style="display:inline-block;background:#166534;color:#fff;border-radius:999px;padding:0 9px;margin-right:6px">\'+n+\'단계</span>\'+t+\'</div><div style="margin-top:6px">\'+body+\'</div></div>\';\n const proofs=c.sources.filter(x=>c.proof.includes(x[0])).map(x=>\'<b>\'+iqMark(x[1])+\'</b>\').join(\', \');\n return \'<div style="background:#ECFDF3;border:2px solid #86EFAC;border-radius:14px;padding:12px 14px;margin-top:8px;line-height:1.7"><b style="font-size:1.1rem;color:#166534">✓ 근거 연결 완료 · 📖 단계별 풀이</b>\'\n +step(1,\'자료 읽기 · 무엇이 근거이고 무엇이 아닐까?\',\'<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:10px;overflow:hidden;font-size:.95rem">\'+rows+\'</table>\')\n +step(2,\'결론 고르기\',\'<b>“\'+esc(c.options[c.answer])+\'”</b>\'+(c.chain?\'<br>👉 \'+esc(c.chain):\'\'))\n +step(3,\'근거 체크하고 제출\',proofs+\'에 체크하면 결론이 한 줄로 이어져요.\')\n +\'<div style="margin-top:10px;background:#fff;border-radius:10px;padding:8px 12px">💬 <b>핵심 요령</b> · \'+esc(c.lesson)+\'</div></div>\';}\nfunction iqHint(i){const c=IQ_CASES[i],s0=iqState(i);if(s0.hints>=iqHintList(c).length)return;iqState(i).hints++;if(typeof iqHintUsed===\'function\')iqHintUsed(i);render();}\nfunction iqCheck(i){const s=iqState(i),c=IQ_CASES[i];if(s.done)return;\n if(s.choice===\'\'){s.error=\'👇 먼저 결론을 하나 골라 주세요.\';render();return;}\n if(s.selected.length!==c.proof.length){s.error=\'☑️ 근거 자료를 정확히 \'+c.proof.length+\'개 체크해 주세요. (지금 \'+s.selected.length+\'개)\';render();return;}\n s.tries++;\n const ok=Number(s.choice)===c.answer&&c.proof.every(k=>s.seen.includes(k)&&s.selected.includes(k));\n if(ok){s.done=true;s.error=\'\';iqComplete(i);}\n else{const okChoice=Number(s.choice)===c.answer;\n  // 결론이 틀렸는지, 근거가 틀렸는지 나눠서 알려 줘요(정답은 알려 주지 않아요).\n  s.error=okChoice?\'👍 결론은 맞아요! 근거 자료만 다시 골라 봐요.\':\'🤔 결론이 달라요. 자료를 순서대로 다시 이어 봐요!\';if(typeof iqWrong===\'function\')iqWrong(i);render();}\n}\nfunction iqReset(){for(const k of Object.keys(IQ_STATE))delete IQ_STATE[k];}\n'
def attach(html):
    payload=json.dumps(CASES,ensure_ascii=False).replace("<","\\u003c")
    html = html.replace("</head>", IQ_CSS_PY + "</head>", 1) if "</head>" in html else IQ_CSS_PY + html
    return html.replace("<script>", "<script>\nconst IQ_CASES="+payload+";\n"+JS+"\n",1)
